script:
class Component extends DCLogic {
shared(k, d) { try { var S = parent.SONNA_STORE; return S ? S.get(k, d) : d; } catch (e) { return d; } }
saveShared(k, v) { let r = false; try { r = parent.SONNA_STORE ? parent.SONNA_STORE.set(k, v) : false; } catch (e) {} if (!r) this._fail = true; return r; }
data() {
const d = this.dataBase(); const C = this.shared('catalog', null);
if (!C) return d;
const M = { 'reroll-android': 'ra', 'reroll-ios': 'ri', 'char-android': 'ca', 'char-ios': 'ci', 'team-meta': 'tm' };
const categories = d.cats.slice();
(C.categories || []).forEach((c) => { if (c && c.id && c.name) { M[c.id] = c.id; categories.push({ id: c.id, name: c.name }); } });
const items = [];
(C.subs || []).forEach((x) => { if (M[x.cat]) items.push({ id: x.id, cat: M[x.cat], title: x.title || '(chưa đặt tiêu đề)', price: x.price }); });
(C.accts || []).forEach((a) => { if ((['char-android', 'char-ios', 'team-meta'].indexOf(a.cat) >= 0 || M[a.cat]) && !a.sub && a.status === 'Đang bán') items.push({ id: a.id, cat: M[a.cat], title: a.title || 'Acc #' + a.id, price: a.price }); });
return { cats: categories, items };
}
dataBase() {
return {
cats: [
{ id: 'ra', name: 'Reroll DBL Android' }, { id: 'ri', name: 'Reroll DBL iOS' }, { id: 'ca', name: 'Character + Chrono Android' }, { id: 'ci', name: 'Character + Chrono iOS' }, { id: 'tm', name: 'Team Meta' }
],
items: [
{ id: 'ra50', cat: 'ra', title: 'DBL 50K-55K APK', price: 10000 }, { id: 'ra60', cat: 'ra', title: 'DBL 60K-65K APK', price: 20000 }, { id: 'ra70', cat: 'ra', title: 'DBL 70K-75K APK', price: 45000 }, { id: 'ra80', cat: 'ra', title: 'DBL 80K-85K APK', price: 80000 }, { id: 'ra90', cat: 'ra', title: 'DBL 90K-95K APK', price: 100000 },
{ id: 'ri50', cat: 'ri', title: 'DBL 50K-55K iOS', price: 18000 }, { id: 'ri60', cat: 'ri', title: 'DBL 60K-65K iOS', price: 30000 }, { id: 'ri70', cat: 'ri', title: 'DBL 70K-75K iOS', price: 60000 },
{ id: 'CA-1042', cat: 'ca', title: 'Acc #CA-1042', price: 1250000 }, { id: 'CA-1039', cat: 'ca', title: 'Acc #CA-1039', price: 3400000 }, { id: 'CA-1037', cat: 'ca', title: 'Acc #CA-1037', price: 320000 },
{ id: 'CI-1041', cat: 'ci', title: 'Acc #CI-1041', price: 690000 }, { id: 'CI-1034', cat: 'ci', title: 'Acc #CI-1034', price: 2150000 },
{ id: 'TM-0008', cat: 'tm', title: 'Acc #TM-0008', price: 1800000 }, { id: 'TM-0011', cat: 'tm', title: 'Acc #TM-0011', price: 2600000 }
]
};
}
defOrder() { const d = this.data(); const o = {}; d.cats.forEach((c) => { o[c.id] = d.items.filter((i) => i.cat === c.id).map((i) => i.id); }); return o; }
defBanners() {
return [
{ id: 1, kind: 'main', title: 'ACC REROLL UY TÍN, GIAO TỰ ĐỘNG', link: '/acc-reroll', on: true, img: '', kicker: 'SONNA · ACC DRAGON BALL LEGENDS', sub: 'Thanh toán bằng ví, nhận TK|MK ngay sau khi trừ tiền.', bg: 'linear-gradient(120deg,#2D0A3F,#5B1F7A 60%,#8A3FB0)' },
{ id: 2, kind: 'main', title: 'NẠP VÍ THƯỞNG THÊM 5%', link: '/nap-tien', on: true, img: '', kicker: 'KHUYẾN MÃI NẠP', sub: 'Nạp 100.000₫ nhận 105.000₫. Nạp ngân hàng hoặc thẻ cào.', bg: 'linear-gradient(120deg,#102A56,#2F6FD6 70%,#58A0F0)' },
{ id: 3, kind: 'sub', title: 'Mua 1 tặng 1', link: '', on: true, img: '', kicker: '', sub: 'Một số gói reroll được tặng thêm 1 acc cùng loại, giao tự động ngay khi thanh toán. Mua nhiều acc vẫn chỉ tặng 1.', bg: '#fff' }
];
}
themeOf(id, color, accent) {
const presets = {
royal: { name: 'Tím SONNA', primary: '#2D0A3F', mid: '#3F1457', deep: '#220733', tint: '#F3E8F9', border: '#D9CFE6', footerMuted: '#B8A3CF', accent: '#FF8A1F', accentLight: '#FFC24B', text: '#FFFFFF' },
navy: { name: 'Navy hiện đại', primary: '#17334F', mid: '#294D70', deep: '#0C2033', tint: '#EAF2F8', border: '#D2E1EA', footerMuted: '#B5CBD8', accent: '#E6AD4F', accentLight: '#F0C56E', text: '#FFFFFF' },
emerald: { name: 'Emerald chuyên nghiệp', primary: '#0D5148', mid: '#1E6C61', deep: '#07352F', tint: '#E8F4F1', border: '#CFE5DF', footerMuted: '#B2D4CD', accent: '#D8A64B', accentLight: '#F0C56E', text: '#FFFFFF' }
};
if (presets[id]) return { id, ...presets[id] };
const base = /^#[0-9a-f]{6}$/i.test(color || '') ? color : '#2D0A3F';
const mix = (hex, target, amount) => { const a = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16)); const b = [1, 3, 5].map((i) => parseInt(target.slice(i, i + 2), 16)); return '#' + a.map((v, i) => Math.round(v + (b[i] - v) * amount).toString(16).padStart(2, '0')).join('').toUpperCase(); };
const rgb = [1, 3, 5].map((i) => parseInt(base.slice(i, i + 2), 16) / 255).map((v) => v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
const luminance = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
const text = 1.05 / (luminance + 0.05) >= (luminance + 0.05) / 0.052 ? '#FFFFFF' : '#1A1206';
return { id: 'custom', name: 'Màu tùy chỉnh', primary: base, mid: mix(base, '#FFFFFF', 0.14), deep: mix(base, '#000000', 0.2), tint: mix(base, '#FFFFFF', 0.93), border: mix(base, '#FFFFFF', 0.82), footerMuted: mix(base, '#FFFFFF', 0.76), accent: /^#[0-9a-f]{6}$/i.test(accent || '') ? accent : '#FF8A1F', accentLight: '#FFC24B', text };
}
state = {
tab: 'banner', saved: false, imgErr: 'Chọn file ảnh PNG, JPG, GIF hoặc WebP.',
banners: this.shared('banners', null) || this.defBanners(),
nextId: 100,
marqOn: this.shared('marq', { on: true }).on !== false,
speed: this.shared('marq', { speed: 'mid' }).speed || 'mid',
tone: this.shared('marq', { tone: 'orange' }).tone || 'orange',
marqText: this.shared('marq', null) ? this.shared('marq', null).text : 'Nạp ví hôm nay nhận thêm 5% giá trị nạp\nAcc được admin đăng nhập kiểm tra trước khi đăng bán\nHỗ trợ qua Zalo trong giờ làm việc',
contact: this.shared('contact', null) || {
phone: { v: '[SỐ ĐIỆN THOẠI]', on: true },
zalo: { v: '[SỐ ZALO]', on: true },
fanpage: { v: '[LINK FANPAGE]', on: true },
zgroup: { v: '[LINK NHÓM ZALO]', on: true },
email: { v: '[EMAIL HỖ TRỢ]', on: false },
youtube: { v: '[LINK KÊNH YOUTUBE]', on: false }
},
hours: this.shared('hours', '08:00 - 22:00 hằng ngày'),
catOrder: this.shared('catOrder', ['ra', 'ri', 'ca', 'ci', 'tm']),
itemOrder: this.shared('itemOrder', null) || this.defOrder(),
salesDisplay: this.shared('salesDisplay', { enabled: true, limit: 6 }) || { enabled: true, limit: 6 },
ordCat: 'ra',
theme: this.shared('brandTheme', null) || this.themeOf('royal')
};
renderVals() {
const on = '#FF8A1F', off = '#A3ACC4', ok = '#43D9A0';
const st = this.state;
const theme = st.theme || this.themeOf('royal');
const themePresets = [{ id: 'royal', name: 'Tím SONNA', description: 'Nhận diện thương hiệu sang trọng, nổi bật.', color: '#2D0A3F', mid: '#3F1457', accent: '#FF8A1F', accentLight: '#FFC24B', text: '#FFFFFF' }, { id: 'navy', name: 'Navy hiện đại', description: 'Tin cậy, gọn gàng và chuyên nghiệp.', color: '#17334F', mid: '#294D70', accent: '#E6AD4F', accentLight: '#F0C56E', text: '#FFFFFF' }, { id: 'emerald', name: 'Emerald chuyên nghiệp', description: 'Cao cấp, dịu mắt và khác biệt.', color: '#0D5148', mid: '#1E6C61', accent: '#D8A64B', accentLight: '#F0C56E', text: '#FFFFFF' }].map((x) => ({ ...x, selected: theme.id === x.id, border: theme.id === x.id ? x.color : '#2B3248', pick: () => this.setState({ theme: this.themeOf(x.id), saved: false }) }));
const nav = [
{ label: 'Tổng quan', href: 'AdminDashboard.dc.html' },
{ label: 'Quản lý acc', href: 'AdminAccounts.dc.html' },
{ label: 'Đơn hàng', href: 'AdminOrders.dc.html' },
{ label: 'Thanh toán', href: 'AdminPayments.dc.html' },
{ label: 'Người dùng', href: 'AdminUsers.dc.html' },
{ label: 'Khuyến mãi', href: 'AdminPromos.dc.html' },
{ label: 'Nội dung website', href: 'AdminContent.dc.html', active: true },
{ label: 'Báo cáo', href: '#bao-cao' },
{ label: 'Phân quyền', href: 'AdminRoles.dc.html' },
{ label: 'Nhật ký hoạt động', href: '#nhat-ky' }
].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));

const tabs = [
{ id: 'theme', label: 'Màu giao diện' },
{ id: 'banner', label: 'Banner trang chủ' },
{ id: 'marq', label: 'Chữ chạy thông báo' },
{ id: 'contact', label: 'Thông tin liên hệ' },
{ id: 'sales', label: 'Acc đã bán' }, { id: 'order', label: 'Thứ tự hiển thị' }
].map((t) => ({ ...t, pick: () => this.setState({ tab: t.id, saved: false }), line: t.id === st.tab ? on : 'transparent', fg: t.id === st.tab ? '#EAEFFA' : off }));

const upd = (id, patch) => this.setState({ saved: false, banners: this.state.banners.map((b) => (b.id === id ? { ...b, ...patch } : b)) });
const move = (id, dir) => {
const arr = this.state.banners.slice();
const i = arr.findIndex((b) => b.id === id);
const kind = arr[i].kind;
let j = i + dir;
while (j >= 0 && j < arr.length && arr[j].kind !== kind) j += dir;
if (j < 0 || j >= arr.length) return;
const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
this.setState({ banners: arr, saved: false });
};
const banners = st.banners.map((b) => ({
...b,
hasImg: !!b.img, noImg: !b.img,
clearImg: () => upd(b.id, { img: '' }),
onFile: (e) => {
const f = e.target.files && e.target.files[0];
if (!f) return;
if (!/^image\//.test(f.type)) { this.setState({ imgErr: 'Chọn file ảnh (PNG, JPG, WebP).' }); return; }
if (f.size > 8 * 1024 * 1024) { this.setState({ imgErr: 'Ảnh quá lớn, tối đa 8MB.' }); return; }
const rd = new FileReader();
rd.onload = () => {
if (f.type.toLowerCase() === 'image/gif' || f.type.toLowerCase() === 'image/webp') {
const dataUrl = typeof rd.result === 'string' ? rd.result : '';
if (!dataUrl) { this.setState({ imgErr: 'Không đọc được file ảnh này.' }); return; }
this.setState({ imgErr: '' });
upd(b.id, { img: dataUrl });
return;
}
const im = new Image();
im.onload = () => {
const max = b.kind === 'main' ? 1600 : 900;
const k = Math.min(1, max / im.width);
const cv = document.createElement('canvas');
cv.width = Math.round(im.width * k); cv.height = Math.round(im.height * k);
cv.getContext('2d').drawImage(im, 0, 0, cv.width, cv.height);
this.setState({ imgErr: '' });
upd(b.id, { img: cv.toDataURL('image/jpeg', 0.85) });
};
im.onerror = () => this.setState({ imgErr: 'Không đọc được file ảnh này.' });
im.src = rd.result;
};
rd.readAsDataURL(f);
},
size: b.kind === 'main' ? '1200×420' : '600×300',
slot: b.kind === 'main' ? 'Banner lớn' : 'Banner phụ',
op: b.on ? 1 : 0.45,
on: b.on,
trackBg: b.on ? on : '#2B3248',
justify: b.on ? 'flex-end' : 'flex-start',
stateText: b.on ? 'Đang hiện' : 'Đang ẩn',
stateCol: b.on ? ok : off,
onTitle: (e) => upd(b.id, { title: e.target.value }),
onLink: (e) => upd(b.id, { link: e.target.value }),
toggle: () => upd(b.id, { on: !b.on }),
up: () => move(b.id, -1),
down: () => move(b.id, 1),
remove: () => this.setState({ banners: this.state.banners.filter((x) => x.id !== b.id), saved: false })
}));
const add = (kind) => this.setState({ saved: false, nextId: st.nextId + 1, banners: [...st.banners, { id: st.nextId, kind, title: kind === 'main' ? 'Banner lớn mới' : 'Banner phụ mới', link: '', on: false, img: '', kicker: '', sub: '' }] });

const lines = st.marqText.split('\n').map((s) => s.trim()).filter((s) => s !== '');
const durBase = { slow: 14, mid: 9, fast: 5 }[st.speed];
const dur = Math.max(durBase, Math.round(lines.join('   •   ').length / 8 * (durBase / 9))) + 's';
const tones = { orange: ['#FF8A1F', '#1A1206'], blue: ['#52C7FF', '#0A1620'], dark: ['#1F2538', '#EAEFFA'] }[st.tone];

const labels = { phone: ['Số điện thoại', '[SỐ ĐIỆN THOẠI]'], zalo: ['Zalo cá nhân', '[SỐ ZALO]'], fanpage: ['Fanpage', '[LINK FANPAGE]'], zgroup: ['Nhóm Zalo', '[LINK NHÓM ZALO]'], email: ['Email hỗ trợ', '[EMAIL HỖ TRỢ]'], youtube: ['Kênh YouTube', '[LINK KÊNH YOUTUBE]'] };
const setC = (k, patch) => this.setState({ saved: false, contact: { ...this.state.contact, [k]: { ...this.state.contact[k], ...patch } } });
const fields = Object.keys(labels).map((k) => ({
label: labels[k][0], ph: labels[k][1], value: st.contact[k].v, on: st.contact[k].on,
onChange: (e) => setC(k, { v: e.target.value }),
toggle: () => setC(k, { on: !st.contact[k].on }),
trackBg: st.contact[k].on ? on : '#2B3248', justify: st.contact[k].on ? 'flex-end' : 'flex-start',
stateText: st.contact[k].on ? 'Hiện' : 'Ẩn', stateCol: st.contact[k].on ? ok : off
}));
const previewLines = Object.keys(labels).filter((k) => st.contact[k].on).map((k) => ({ k: labels[k][0], v: st.contact[k].v || '(trống)' }));
if (st.contact.phone.on || st.contact.zalo.on) previewLines.push({ k: 'Giờ hỗ trợ', v: st.hours });

const D = this.data();
const co = st.catOrder.filter((id) => D.cats.some((c) => c.id === id)).concat(D.cats.map((c) => c.id).filter((id) => st.catOrder.indexOf(id) < 0));
const mv = (arr, i, dir) => { const j = i + dir; if (j < 0 || j >= arr.length) return arr; const a = arr.slice(); const t = a[i]; a[i] = a[j]; a[j] = t; return a; };
const catRows = co.map((id, i) => ({ n: i + 1, name: D.cats.find((c) => c.id === id).name, up: () => this.setState({ catOrder: mv(co, i, -1), saved: false }), down: () => this.setState({ catOrder: mv(co, i, 1), saved: false }) }));
const ordCats = D.cats.map((c) => ({ id: c.id, name: c.name, sel: c.id === st.ordCat }));
const ids = (st.itemOrder[st.ordCat] || []).filter((id) => D.items.some((x) => x.id === id)).concat(D.items.filter((x) => x.cat === st.ordCat && (st.itemOrder[st.ordCat] || []).indexOf(x.id) < 0).map((x) => x.id));
const setItems = (arr) => this.setState({ itemOrder: { ...st.itemOrder, [st.ordCat]: arr }, saved: false });
const itemRows = ids.map((id, i) => { const x = D.items.find((y) => y.id === id); return { n: i + 1, title: x.title, price: String(x.price).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫', up: () => setItems(mv(ids, i, -1)), down: () => setItems(mv(ids, i, 1)) }; });
const salesLimit = [3, 6, 9, 12].includes(Number(st.salesDisplay.limit)) ? Number(st.salesDisplay.limit) : 6;

return {
catRows, ordCats, itemRows, onOrdCat: (e) => this.setState({ ordCat: e.target.value }),
imgErr: st.imgErr !== '', imgErrText: st.imgErr,
nav, tabs, banners,
isTheme: st.tab === 'theme',
themePresets, themeColor: /^#[0-9a-f]{6}$/i.test(theme.primary || '') ? theme.primary : '#2D0A3F', themeAccent: theme.accent,
onThemeColor: (e) => this.setState({ theme: this.themeOf('custom', e.target.value, theme.accent), saved: false }),
isSales: st.tab === 'sales',
isOrder: st.tab === 'order', isBanner: st.tab === 'banner', isMarq: st.tab === 'marq', isContact: st.tab === 'contact',
saved: st.saved,
salesOn: st.salesDisplay.enabled !== false,
salesLimit: String(salesLimit),
salesLimitOpts: [3, 6, 9, 12].map((n) => ({ n, sel: n === salesLimit })),
salesTrack: st.salesDisplay.enabled !== false ? on : '#2B3248',
salesJustify: st.salesDisplay.enabled !== false ? 'flex-end' : 'flex-start',
toggleSales: () => this.setState({ salesDisplay: { ...st.salesDisplay, enabled: st.salesDisplay.enabled === false }, saved: false }),
onSalesLimit: (e) => this.setState({ salesDisplay: { ...st.salesDisplay, limit: Math.min(12, Math.max(1, Number(e.target.value) || 6)) }, saved: false }),
onSave: () => {
this._fail = false;
this.saveShared('banners', st.banners);
this.saveShared('marq', { on: st.marqOn, speed: st.speed, tone: st.tone, text: st.marqText });
this.saveShared('contact', st.contact);
this.saveShared('hours', st.hours);
this.saveShared('catOrder', co);
this.saveShared('itemOrder', st.itemOrder);
this.saveShared('salesDisplay', { enabled: st.salesDisplay.enabled !== false, limit: salesLimit });
this.saveShared('brandTheme', theme);
this.setState(this._fail ? { saved: false, imgErr: 'Không lưu được: bộ nhớ trình duyệt đầy (thường do ảnh banner quá nặng). Hãy dùng ảnh nhỏ hơn.' } : { saved: true, imgErr: '' });
},
addMain: () => add('main'), addSub: () => add('sub'),
mainShown: st.banners.filter((b) => b.kind === 'main' && b.on).length,
subShown: st.banners.filter((b) => b.kind === 'sub' && b.on).length,
marqOn: st.marqOn,
marqTrack: st.marqOn ? on : '#2B3248', marqJustify: st.marqOn ? 'flex-end' : 'flex-start',
toggleMarq: () => this.setState({ marqOn: !st.marqOn, saved: false }),
marqText: st.marqText,
onMarqText: (e) => this.setState({ marqText: e.target.value, saved: false }),
sp: { slow: st.speed === 'slow', mid: st.speed === 'mid', fast: st.speed === 'fast' },
tn: { orange: st.tone === 'orange', blue: st.tone === 'blue', dark: st.tone === 'dark' },
onSpeed: (e) => this.setState({ speed: e.target.value, saved: false }),
onTone: (e) => this.setState({ tone: e.target.value, saved: false }),
toneBg: tones[0], toneFg: tones[1],
marqOpacity: st.marqOn ? 1 : 0.4,
marqDur: dur,
marqLine: lines.length ? lines.join('   •   ') : '(chưa có nội dung)',
marqState: st.marqOn ? 'Đang bật: ' + lines.length + ' thông báo chạy lần lượt.' : 'Đang tắt: khách sẽ không thấy thanh này.',
fields, hours: st.hours,
onHours: (e) => this.setState({ hours: e.target.value, saved: false }),
previewLines, noPreview: previewLines.length === 0
};
}
}
